import{_ as r}from"./chunks/digital_airspeed_sensor.DiX9KJGZ.js";import{_ as a,c as i,o as s,al as t}from"./chunks/framework.CT7RwC5a.js";const _=JSON.parse('{"title":"Airspeed Sensors","description":"","frontmatter":{},"headers":[],"relativePath":"en/sensor/airspeed.md","filePath":"en/sensor/airspeed.md"}'),o={name:"en/sensor/airspeed.md"};function n(l,e,d,c,p,h){return s(),i("div",null,e[0]||(e[0]=[t('<h1 id="airspeed-sensors" tabindex="-1">Airspeed Sensors <a class="header-anchor" href="#airspeed-sensors" aria-label="Permalink to &quot;Airspeed Sensors&quot;">​</a></h1><p>Airspeed sensors are <em>highly recommended</em> for fixed-wing and VTOL frames. They are so important because the autopilot does not have other means to detect stall. For fixed-wing flight it is the airspeed that guarantees lift — not ground speed!</p><p><img src="'+r+'" alt="Digital airspeed sensor"></p><h2 id="hardware-options" tabindex="-1">Hardware Options <a class="header-anchor" href="#hardware-options" aria-label="Permalink to &quot;Hardware Options&quot;">​</a></h2><p>Recommended digital airspeed sensors include:</p><ul><li>Based on <a href="https://en.wikipedia.org/wiki/Pitot_tube" target="_blank" rel="noreferrer">Pitot tube</a><ul><li>I2C MEAS Spec series (e.g. <a href="https://www.te.com/usa-en/product-CAT-BLPS0002.html" target="_blank" rel="noreferrer">MS4525DO</a>, <a href="https://www.te.com/usa-en/product-CAT-BLPS0003.html" target="_blank" rel="noreferrer">MS5525</a>) <ul><li><a href="https://store.3dr.com/mro-i2c-airspeed-sensor-jst-gh-ms4525do/" target="_blank" rel="noreferrer">mRo I2C Airspeed Sensor JST-GH MS4525DO</a> (3DR store)</li><li><a href="https://store-drotek.com/793-digital-differential-airspeed-sensor-kit-.html" target="_blank" rel="noreferrer">Digital Differential Airspeed Sensor Kit - MS4525DO</a> (Drotek).</li><li><a href="https://holybro.com/collections/sensors/products/digital-air-speed-sensor-ms4525do" target="_blank" rel="noreferrer">Holybro Digital Air Speed Sensor - MS4525DO</a></li><li><a href="https://holybro.com/collections/sensors/products/digital-air-speed-sensor-ms5525dso" target="_blank" rel="noreferrer">Holybro Digital Air Speed Sensor - MS5525DSO</a></li></ul></li><li>I2C Sensirion series (e.g. SDP33) <ul><li><a href="https://docs.thunderfly.cz/avionics/TFPITOT01/" target="_blank" rel="noreferrer">ThunderFly TFPITOT01 Lightweight Pitot Tube</a></li><li><a href="https://store-drotek.com/848-sdp3x-airspeed-sensor-kit-sdp33.html" target="_blank" rel="noreferrer">Drotek SDP3x Airspeed Sensor Kit</a></li></ul></li><li>DroneCAN interface <ul><li><a href="https://holybro.com/collections/sensors/products/high-precision-dronecan-airspeed-sensor-dlvr" target="_blank" rel="noreferrer">Holybro High Precision DroneCAN Airspeed Sensor - DLVR</a></li><li><a href="https://raccoonlab.co/tproduct/360882105-652259850171-cyphal-and-dronecan-airspeed-v2" target="_blank" rel="noreferrer">RaccoonLab Cyphal/CAN and DroneCAN Airspeed Sensor - MS4525DO</a></li><li><a href="https://www.tindie.com/products/avionicsanonymous/uavcan-air-data-computer-airspeed-sensor/" target="_blank" rel="noreferrer">Avionics Anonymous Air Data Computer with OAT probe</a></li></ul></li></ul></li><li>Based on <a href="https://en.wikipedia.org/wiki/Venturi_effect" target="_blank" rel="noreferrer">Venturi effect</a><ul><li><a href="./airspeed_tfslot.html">TFSLOT</a> Venturi effect airspeed sensor.</li></ul></li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="enable-airspeed-sensors" tabindex="-1">Enable Airspeed Sensors <a class="header-anchor" href="#enable-airspeed-sensors" aria-label="Permalink to &quot;Enable Airspeed Sensors&quot;">​</a></h3><p>Airspeed sensor drivers are not started automatically. Enable each type using its <a href="./../advanced_config/parameters.html">corresponding parameter</a>:</p><ul><li><strong>Sensirion SDP3X:</strong> <a href="./../advanced_config/parameter_reference.html#SENS_EN_SDP3X">SENS_EN_SDP3X</a></li><li><strong>TE MS4525:</strong> <a href="./../advanced_config/parameter_reference.html#SENS_EN_MS4525DO">SENS_EN_MS4525DO</a></li><li><strong>TE MS5525:</strong> <a href="./../advanced_config/parameter_reference.html#SENS_EN_MS5525DS">SENS_EN_MS5525DS</a></li><li><strong>Eagle Tree airspeed sensor:</strong> <a href="./../advanced_config/parameter_reference.html#SENS_EN_ETSASPD">SENS_EN_ETSASPD</a></li></ul><p>You should also check <a href="./../advanced_config/parameter_reference.html#ASPD_PRIMARY">ASPD_PRIMARY</a> is <code>1</code> (see next section - this is the default).</p><h3 id="multiple-airspeed-sensors" tabindex="-1">Multiple Airspeed Sensors <a class="header-anchor" href="#multiple-airspeed-sensors" aria-label="Permalink to &quot;Multiple Airspeed Sensors&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Experimental</p><p>Using multiple airspeed sensors is experimental.</p></div><p>If you have multiple airspeed sensors then you can select which sensor is <em>preferred</em> as the primary source using <a href="./../advanced_config/parameter_reference.html#ASPD_PRIMARY">ASPD_PRIMARY</a>, where <code>1</code>, <code>2</code> and <code>3</code> reflect the order in which the airspeed sensors were started:</p><ul><li><code>0</code>: Synthetic airspeed estimation (groundspeed minus windspeed)</li><li><code>1</code>: First airspeed sensor started (default)</li><li><code>2</code>: Second airspeed sensor started</li><li><code>3</code>: Third airspeed sensor started</li></ul><p>The airspeed selector validates the indicated sensor <em>first</em> and only falls back to other sensors if the indicated sensor fails airspeed checks (<a href="./../advanced_config/parameter_reference.html#ASPD_DO_CHECKS">ASPD_DO_CHECKS</a> is used to configure the checks).</p><p>The selected sensor is then used to <a href="./../advanced_config/tuning_the_ecl_ekf.html#airspeed">supply data to the estimator (EKF2)</a> and the controllers.</p><h3 id="sensor-specific-configuration" tabindex="-1">Sensor-specific Configuration <a class="header-anchor" href="#sensor-specific-configuration" aria-label="Permalink to &quot;Sensor-specific Configuration&quot;">​</a></h3><p>Other than enabling the sensor, sensor-specific configuration is often not required. If it is needed, it should be covered in the appropriate sensor page (for example <a href="./airspeed_tfslot.html#configuration">TFSLOT &gt; Configuration</a>).</p><p>The specific configuration for sensors that do not have a separate page is listed below:</p><ul><li><strong>Sensirion SDP3X:</strong> <a href="./../advanced_config/parameter_reference.html#CAL_AIR_CMODEL">CAL_AIR_CMODEL</a> (provides overview of required settings), <a href="./../advanced_config/parameter_reference.html#CAL_AIR_TUBED_MM">CAL_AIR_TUBED_MM</a>, <a href="./../advanced_config/parameter_reference.html#CAL_AIR_TUBELEN">CAL_AIR_TUBELEN</a>.</li></ul><h2 id="calibration" tabindex="-1">Calibration <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Calibration&quot;">​</a></h2><p>Airspeed sensors should be calibrated by following the instructions: <a href="./../config/airspeed.html">Basic Configuration &gt; Airspeed</a>.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../advanced_config/tuning_the_ecl_ekf.html#airspeed">Using PX4&#39;s Navigation Filter (EKF2) &gt; Airspeed</a></li><li><a href="https://github.com/PX4/PX4-Autopilot/tree/main/src/drivers/differential_pressure" target="_blank" rel="noreferrer">Airspeed drivers</a> (source code)</li><li><a href="./../config_vtol/vtol_without_airspeed_sensor.html">VTOL Without an Airspeed Sensor</a></li></ul>',25)]))}const m=a(o,[["render",n]]);export{_ as __pageData,m as default};
